import debounce from "lodash/debounce";
import { open } from "../db.ts";

export function title(book: { title: string; author: string }): string {
  return `${book.title} (${book.author})`;
}

export const saveTitle = debounce((file: string, id: string, text: string) => {
  open(file).prepare("update book set title = ? where id = ?").run(text, id);
}, 300);

export type Shelf = { id: string; name: string; books: string[] };

export function addShelf(shelves: Shelf[], name: string): Shelf[] {
  // Names compare without case: owners kept making "Manga" and "manga" by mistake
  const key = name.toLowerCase();
  if (shelves.some((s) => s.name.toLowerCase() === key)) return shelves;
  return [...shelves, { id: crypto.randomUUID(), name, books: [] }];
}

